#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int totalPoints;
    cin >> totalPoints;
    if (totalPoints >= 100) {
        cout << 0 << "\n";
    } else {
        vector<vector<int>> coords(totalPoints + 1, vector<int>(5));
        for (int index = 1; index <= totalPoints; index++) {
            for (int dim = 0; dim < 5; dim++) {
                cin >> coords[index][dim];
            }
        }
        unordered_set<int> invalidIndices;
        for (int i = 1; i <= totalPoints; i++) {
            for (int j = 1; j <= totalPoints; j++) {
                for (int k = 1; k <= totalPoints; k++) {
                    if (i == j || j == k || k == i) continue;
                    std::vector<long long> vecA(5), vecB(5);
                    for (int d = 0; d < 5; d++) {
                        vecA[d] = coords[j][d] - coords[i][d];
                        vecB[d] = coords[k][d] - coords[i][d];
                    }
                    long double dotProduct = 0.0;
                    long long lengthA = 0, lengthB = 0;
                    for (int d = 0; d < 5; d++) {
                        dotProduct += (long double)vecA[d] * vecB[d];
                        lengthA += (long long)vecA[d] * vecA[d];
                        lengthB += (long long)vecB[d] * vecB[d];
                    }
                    long double denom = sqrtl((long double)lengthA) * sqrtl((long double)lengthB);
                    if (denom == 0) continue; // avoid division by zero
                    long double cosine = dotProduct / denom;
                    long double angleDeg = acosl(cosine) * 180.0 / M_PI;
                    if (angleDeg + 1e-9 < 90.0) {
                        invalidIndices.insert(i);
                    }
                }
            }
        }
        cout << totalPoints - (int)invalidIndices.size() << "\n";
        for (int i = 1; i <= totalPoints; i++) {
            if (invalidIndices.find(i) == invalidIndices.end()) {
                cout << i << "\n";
            }
        }
    }
    return 0;
}
